import { useTheme } from "../context/ThemeContext";

/**
 * A docs illustration in the reader's theme. Both variants are generated by
 * `bun run docs:illustrations`; the app's theme (not the OS) picks one.
 * @param props - The illustration name (`<name>-{light,dark}.png`) and alt text.
 * @returns The image.
 */
export function ThemedImage({ name, alt }: { name: string; alt: string }) {
  const { resolved } = useTheme();
  return (
    <img
      className="themed-image"
      src={`/doc-assets/illustrations/${name}-${resolved}.png`}
      alt={alt}
      data-theme-variant={resolved}
      loading="lazy"
    />
  );
}
